let playerGroup='all',partnerPage=0,partnerPaused=false,partnerLastChange=0;
function clubNav(){return '<div class="club-navigation"><button data-action="achievements"><span class="club-nav-index" aria-hidden="true">01</span><span class="club-nav-text"><small>Historie klubu</small><strong>Úspěchy klubu</strong></span><span class="club-nav-arrow" aria-hidden="true">→</span></button><button data-action="players"><span class="club-nav-index" aria-hidden="true">02</span><span class="club-nav-text"><small>Aktuální tým</small><strong>Profily hráčů</strong></span><span class="club-nav-arrow" aria-hidden="true">→</span></button></div>'}
function clubHeading(title){return `<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">FC BANÍK OSTRAVA</span></div><div class="club-page-heading"><span class="eyebrow">MODROBÍLÉ SRDCE OSTRAVY</span><h1>${title}</h1></div>`}
const HISTORY_ERAS=[['all','Celý příběh',0,9999],['start','1922–1949',0,1949],['gold','1950–1979',1950,1979],['second','1980–1999',1980,1999],['modern','2000–dnes',2000,9999]];
// League titles, from https://www.fcb.cz/zobraz.asp?t=historie-uspechy
const TITLES=[['1975 / 1976','Tým Jiřího Rubáše byl po podzimu dvanáctý, na jaře neprohrál osm kol v řadě a výhrou v Plzni slavil první titul.'],['1979 / 1980','Hadamczikův Baník kráčel za titulem od začátku. Mistrem byl čtyři kola před koncem, Lička se stal králem střelců.'],['1980 / 1981','Generace medailistů z ME 1980 obhájila titul a v Poháru mistrů došla do čtvrtfinále proti Bayernu.'],['2003 / 2004','Senzační titul party trenéra Františka Komňackého. Ostravsko zachvátila fotbalová euforie.']];
let historyEra='all';
function historyMilestones(){return (ClubContent.history&&ClubContent.history.milestones)||[]}
function historyPhoto(year){return historyMilestones().find(m=>m.year===year&&m.photos)?.photos[0]}
function milestoneTone(m){if(/titul/i.test(m.label))return 'gold';if(/pohár|medail|bronz|finále/i.test(m.label))return 'silver';if(/sestup/i.test(m.label))return 'down';return ''}
function milestoneCard(m,index){const tone=milestoneTone(m);const photos=(m.photos||[]).map(p=>`<figure class="history-photo"><img src="${esc(p.file)}" alt="${esc(m.label)}" loading="lazy" width="${p.width}" height="${p.height}"><figcaption>${esc(m.label)} · archiv klubu</figcaption></figure>`).join('');return `<article class="history-item ${tone}" style="--i:${index}"><div class="history-marker"><span>${esc(m.year||'·')}</span></div><div class="history-body"><h3>${esc(m.label)}</h3><p>${esc(m.text)}</p>${photos}</div></article>`}
function achievementsScreen(era=historyEra){
  screen='achievements';historyEra=era;
  const all=historyMilestones(),[,,from,to]=HISTORY_ERAS.find(e=>e[0]===era)||HISTORY_ERAS[0];
  const list=all.filter(m=>era==='all'||(m.year!=null&&m.year>=from&&m.year<=to));
  const hero=historyPhoto(1976),photos={'1975 / 1976':historyPhoto(1976),'2003 / 2004':historyPhoto(2004)};
  const silver=['1954/1955','1978/1979','1981/1982','1982/1983','1988/1989','1989/1990'];
  const cups=['Čs. pohár 1972/1973','Čs. pohár 1977/1978','Čs. pohár 1990/1991','Pohár ČMFS 2004/2005'];
  $('#main').innerHTML=clubHeading('Příběh psaný na trávníku.')+`<section class="history-hero">${hero?`<img src="${esc(hero.file)}" alt="Mistři ligy 1975/1976">`:''}<div class="history-hero-text"><span class="eyebrow">OD ROKU 1922 · OSTRAVA</span><h2>Čtyři tituly, čtyři národní poháry a přes sto let modrobílého fotbalu.</h2><p>Od hostince U dubu přes Bazaly, výhru nad Bayernem a semifinále Poháru vítězů pohárů až po návrat do Evropy. Projdi si příběh klubu rok po roce.</p></div></section><div class="history-stats"><div><strong>1922</strong><span>založení klubu</span></div><div class="gold"><strong>4×</strong><span>mistr ligy</span></div><div><strong>6×</strong><span>vicemistr ligy</span></div><div><strong>4×</strong><span>vítěz národního poháru</span></div><div><strong>1979</strong><span>semifinále PVP</span></div></div><div class="champion-cards history-champions">${TITLES.map(([season,text],i)=>`<article>${photos[season]?`<img src="${esc(photos[season].file)}" alt="">`:''}<div><span>0${i+1} / MISTŘI LIGY</span><h2>${season}</h2><p>${text}</p></div></article>`).join('')}</div><section class="kiosk-card club-achievements history-card"><div class="history-head"><div><span class="eyebrow">HISTORICKÉ MEZNÍKY</span><h2>Časová osa klubu</h2></div><div class="player-filters history-filters">${HISTORY_ERAS.map(([id,label])=>`<button data-era="${id}" aria-pressed="${era===id}" class="${era===id?'selected':''}">${label}</button>`).join('')}</div></div><div class="history-timeline">${list.map(milestoneCard).join('')||'<p class="hint">Pro toto období zatím nemáme záznam.</p>'}</div><h2>Šest stříbrných sezón</h2><div class="silver-seasons">${silver.map(s=>`<span>${s}</span>`).join('')}</div><h2>Národní poháry</h2><div class="silver-seasons">${cups.map(s=>`<span>${s}</span>`).join('')}</div><p class="content-source">Časová osa podle <a href="https://www.fcb.cz/zobraz.asp?t=historie" target="_blank" rel="noopener">oficiální historie klubu ↗</a> a <a href="https://www.fcb.cz/zobraz.asp?t=historie-uspechy" target="_blank" rel="noopener">přehledu úspěchů ↗</a>; fotografie archiv klubu.</p></section>`;
}
const POSITION_GROUPS=[['all','Všichni'],['Brankář','Brankáři'],['Obránce','Obránci'],['Záložník','Záložníci'],['Útočník','Útočníci']];
// A player without a portrait on the club site gets the crest instead of a broken image.
function playerPhoto(p){return p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)}" loading="lazy">`:`<img class="photo-fallback" src="${esc(logo)}" alt="${esc(p.name)}">`}
function playersScreen(group=playerGroup){
  screen='players';playerGroup=group;
  const list=ClubContent.players.filter(p=>group==='all'||p.position===group);
  $('#main').innerHTML=clubHeading('Profily hráčů')+`<p class="content-date">Soupiska a statistiky stažené ${fmt(ClubContent.updatedAt,{day:'numeric',month:'long',year:'numeric'})}. Údaje se vztahují k době stažení.</p><div class="player-filters">${POSITION_GROUPS.map(([v,label])=>`<button data-player-group="${v}" aria-pressed="${group===v}" class="${group===v?'selected':''}">${label}</button>`).join('')}</div><div class="roster-grid">${list.map(p=>`<button class="roster-card" data-player-id="${p.id}"><div class="roster-photo"><span class="roster-number">${esc(p.number)}</span>${playerPhoto(p)}</div><div class="roster-label"><small>${esc(p.position)}</small><h2>${esc(p.name)}</h2><span>Otevřít profil →</span></div></button>`).join('')}</div>`;
}
function playerScreen(id){
  const p=ClubContent.players.find(p=>p.id===id);if(!p)return;
  screen='player';
  const competitions=(p.competitions||[]).map(c=>`<article><h3>${esc(c.label)}</h3><p>${Object.entries(c.values).map(([label,value])=>`${esc(label)}: <b>${esc(value)}</b>`).join(' · ')}</p></article>`).join('');
  $('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="players">← Profily hráčů</button><span class="eyebrow">FC BANÍK OSTRAVA</span></div><section class="kiosk-card player-detail"><div class="player-identity"><div class="player-portrait">${playerPhoto(p)}</div><div><span class="eyebrow">#${esc(p.number)} · ${esc(p.position)}</span><h1>${esc(p.name)}</h1><dl><dt>Narození</dt><dd>${esc(p.born||'Neuvedeno')}</dd><dt>Výška / váha</dt><dd>${esc(p.measurements||'Neuvedeno')}</dd><dt>Národnost</dt><dd>${esc(p.nationality||'Neuvedeno')}</dd></dl></div></div><h2>Chance Liga – aktuální sezóna</h2><div class="player-stats">${Object.entries(p.stats).map(([label,value])=>`<div><strong>${esc(value)}</strong><span>${esc(label)}</span></div>`).join('')||'<p class="hint">V lize zatím bez startu.</p>'}</div><h2>Všechny soutěže sezóny</h2><div class="player-career">${competitions||'<p>Klub zatím statistiky v soutěžích neuvádí.</p>'}</div><p class="content-source">Údaje stažené ${fmt(ClubContent.updatedAt,{day:'numeric',month:'numeric',year:'numeric'})} · <a href="${esc(p.source)}" target="_blank" rel="noopener">Oficiální profil hráče ↗</a></p></section>`;
}
function partnerItems(partners){return partners.map((p,i)=>`<div class="partner-tile" style="--i:${i}"><img src="${esc(p.logo)}" alt="${esc(p.name)}"></div>`).join('')}
function partnerGroups(){const groups=[],byCategory=new Map();for(const p of ClubContent.partners){if(p.category==='Generální partner')continue;if(!byCategory.has(p.category))byCategory.set(p.category,[]);byCategory.get(p.category).push(p)}for(const list of byCategory.values())for(let i=0;i<list.length;i+=4)groups.push(list.slice(i,i+4));return groups}
function partnerSlide(group,cls){return `<div class="partner-slide ${cls}"${cls==='partner-leave'?' aria-hidden="true"':''}>${partnerItems(group||[])}</div>`}
function partnerHeading(){const groups=partnerGroups(),group=groups[partnerPage]||[];$('#partner-category').textContent=group[0]?.category||'Partneři klubu';$('#partner-count').textContent=`${partnerPage+1} / ${groups.length}`;$('#partner-progress').innerHTML='<span></span>'}
function initPartners(){
  const general=ClubContent.partners.filter(p=>p.category==='Generální partner');
  $('#partners-strip').innerHTML=`<div class="general-partner"><span class="partner-label">Generální partner</span>${partnerItems(general)}</div><div class="partner-rotator"><div class="partner-rotator-head"><span class="partner-label" id="partner-category"></span><small id="partner-count"></small><div class="partner-controls"><button id="partners-pause" aria-label="Pozastavit střídání partnerů" aria-pressed="false">❚❚</button><button id="partners-next" aria-label="Další partneři">→</button></div></div><div class="partner-frame" id="partner-frame" aria-label="Střídající se partneři">${partnerSlide(partnerGroups()[partnerPage],'partner-enter')}</div><div class="partner-progress" id="partner-progress"></div></div>`;
  partnerLastChange=Date.now();partnerHeading();
  $('#partners-pause').onclick=()=>{partnerPaused=!partnerPaused;$('#partners-pause').textContent=partnerPaused?'▶':'❚❚';$('#partners-pause').setAttribute('aria-pressed',String(partnerPaused));$('#partners-pause').setAttribute('aria-label',partnerPaused?'Spustit střídání partnerů':'Pozastavit střídání partnerů');$('#partners-strip').classList.toggle('paused',partnerPaused);partnerLastChange=Date.now();if(!partnerPaused)$('#partner-progress').innerHTML='<span></span>'};
  $('#partners-next').onclick=()=>rotatePartners();
}
function rotatePartners(){
  const groups=partnerGroups();if(!groups.length)return;
  const previous=groups[partnerPage];partnerPage=(partnerPage+1)%groups.length;
  $('#partner-frame').innerHTML=partnerSlide(previous,'partner-leave')+partnerSlide(groups[partnerPage],'partner-enter');
  partnerLastChange=Date.now();partnerHeading();
}
function tickPartners(){if(!partnerPaused&&Date.now()-partnerLastChange>=8000)rotatePartners()}
